import re


def main(eval_inputs):
    """Fraction of the answer's [Title, p. N] citations that match a retrieved excerpt.

    Checks the PAGE as well as the title. Title-only matching passed anything
    that named a real book, including a page that was never retrieved and
    malformed pages like "32/p. 70" — which is exactly the failure this is
    supposed to catch.
    """
    out = str(eval_inputs.get('output', '') or '')
    inp = str(eval_inputs.get('input', '') or '')

    # What retrieval actually supplied, from the [Title, p. N] excerpt headers.
    available = set()
    for title, page in re.findall(r'\[([^\]]+?),\s*p\.\s*([^\]]+?)\]', inp):
        available.add((title.strip(), page.strip()))
    if not available:
        return 1.0          # no excerpt headers to check against

    cited = []
    for group in re.findall(r'\[([^\]]+)\]', out):
        for piece in group.split(';'):
            m = re.match(r'\s*(.+?),\s*p\.\s*(.+?)\s*$', piece)
            if m:
                cited.append((m.group(1).strip(), m.group(2).strip()))
    if not cited:
        return 1.0          # a refusal asserts nothing, so it mis-cites nothing

    def valid(title, page):
        if (title, page) in available:
            return True
        # "1-2" or "1, 2" is fine when every page in it was retrieved.
        parts = [p.strip() for p in re.split(r'[-–,]', page) if p.strip()]
        return len(parts) > 1 and all((title, p) in available for p in parts)

    # Counted per citation instance, not deduplicated by title: one bad citation
    # among ten good ones should read as 0.9, not as 0.5.
    return round(sum(1 for t, p in cited if valid(t, p)) / len(cited), 2)
